<template><section class="farm-page">
<header class="farm-header"><h1>Farm</h1><span class="farm-state" :class="{running:summary.enabled}">{{ summary.enabled?'Submission enabled':'Submission paused' }} · {{ summary.protocol }}</span><div class="farm-actions"><b-button size="sm" variant="outline-secondary" @click="paused=!paused">{{ paused?'Refresh':'Pause updates' }}</b-button><b-button size="sm" variant="outline-secondary" @click="$root.$emit('gm:farm-settings')"><i class="fas fa-sliders-h" aria-hidden="true"/> Farm settings</b-button></div></header>
<b-alert :show="!!error" variant="danger">{{ error }}</b-alert><b-alert :show="!!summary.lastError" variant="warning">Scoreboard: {{ summary.lastError }}</b-alert>
<nav class="farm-tabs" aria-label="Farm sections"><button v-for="t in tabs" :key="t.key" class="btn btn-sm" :class="tab===t.key?'btn-primary':'btn-outline-secondary'" @click="tab=t.key">{{ t.label }}</button></nav>
<template v-if="tab==='flags'">
<div class="farm-chips"><button class="btn btn-sm" :class="filters.status===''?'btn-primary':'btn-outline-secondary'" @click="selectStatus('')">All · {{ totalAll }}</button><button v-for="s in statuses" :key="s.key" class="btn btn-sm" :class="filters.status===s.key?'btn-primary':'btn-outline-secondary'" @click="selectStatus(s.key)">{{ s.label }} · {{ counts[s.key]||0 }}</button><button class="btn btn-sm btn-outline-primary ml-auto" @click="manual=!manual">{{ manual?'Hide form':'+ Submit manually' }}</button></div>
<form v-if="manual" class="farm-manual" @submit.prevent="submit"><label for="manual-flags">Text containing flags</label><b-form-textarea id="manual-flags" v-model="text" rows="3" :placeholder="config.flagFormat"/><div class="farm-actions mt-2"><span role="status">{{ notice }}</span><b-button size="sm" type="submit" variant="primary" :disabled="sending||!text.trim()">{{ sending?'Adding…':'Add to queue' }}</b-button></div></form>
<form class="farm-filters" @submit.prevent="apply"><label>Search flag / response<b-form-input size="sm" v-model="filters.search"/></label><label>Team<b-form-select size="sm" v-model="filters.team" :options="teamOptions"/></label><label>Exploit<b-form-select size="sm" v-model="filters.sploit" :options="sploitOptions"/></label><label>From<b-form-input size="sm" type="datetime-local" v-model="filters.since"/></label><label>To<b-form-input size="sm" type="datetime-local" v-model="filters.until"/></label><b-button size="sm" type="submit" variant="outline-primary">Find</b-button><b-button size="sm" variant="outline-secondary" @click="reset">Reset</b-button></form>
<div class="farm-table"><table><thead><tr><th>Flag</th><th>Team / exploit</th><th>Status</th><th>Scoreboard response</th><th>Attempts</th><th>Time</th></tr></thead><tbody><tr v-for="f in flags" :key="f.id"><td><button class="farm-copy" @click="copy(f.flag)" title="Copy flag"><code>{{ f.flag }}</code></button></td><td>{{ f.team }}<small>{{ f.sploit }}</small></td><td><span class="farm-badge" :class="f.status.toLowerCase()">{{ label(f.status) }}</span></td><td class="farm-response">{{ f.response||'—' }}</td><td>{{ f.attempts }}</td><td class="text-nowrap" :title="f.created">{{ date(f.created) }}</td></tr><tr v-if="!flags.length"><td colspan="6" class="farm-empty">{{ loading?'Loading…':'No flags found' }}</td></tr></tbody></table></div>
<footer class="farm-pagination"><span role="status">{{ notice||`${total} flags` }}</span><b-button size="sm" :disabled="page<=1||loading" @click="page--;refresh()">←</b-button><span>{{ page }} / {{ Math.max(1,Math.ceil(total/50)) }}</span><b-button size="sm" :disabled="page*50>=total||loading" @click="page++;refresh()">→</b-button></footer></template>
<div v-else-if="tab==='teams'" class="farm-table"><table><thead><tr><th>Team</th><th>IP</th><th v-for="s in statuses" :key="s.key">{{ s.label }}</th></tr></thead><tbody><tr v-for="t in config.targets" :key="t.host"><td>{{ t.name }}</td><td><code>{{ t.host }}</code></td><td v-for="s in statuses" :key="s.key">{{ teamCount(t.name,s.key) }}</td></tr><tr v-if="!config.targets.length"><td colspan="7" class="farm-empty">Add teams in farm settings.</td></tr></tbody></table></div>
<div v-else class="farm-builder"><div class="farm-builder-controls"><h2>Exploit template</h2><label>Filename<b-form-input v-model="filename" size="sm"/></label><label>Protocol<b-form-select v-model="protocol" size="sm" :options="['HTTP','TCP']"/></label><label>Port<b-form-input v-model.number="port" type="number" min="1" max="65535" size="sm"/></label><label v-if="protocol==='HTTP'">Path<b-form-input v-model="path" size="sm"/></label><b-button size="sm" variant="outline-primary" @click="generate">Regenerate template</b-button><b-button size="sm" variant="primary" @click="download(code,filename)">Download exploit</b-button><b-button size="sm" variant="outline-secondary" @click="copy(code)">Copy</b-button><a class="btn btn-sm btn-outline-primary" href="/api/v2/farm/client.py" download>Download Python client</a><p class="small text-muted">The client fetches targets and exclusions from settings each round. The exploit receives the IP as its last argument. Print the response with flush=True; the client extracts flags automatically.</p><p v-if="protocol==='HTTP'" class="small text-muted">For the HTTP template: <code>python3 -m pip install requests</code></p><p class="small">Launch command with your GoMate credentials:</p><pre class="farm-command">{{ command }}</pre><b-button size="sm" variant="outline-secondary" :disabled="!credentials" @click="copy(command)">Copy launch command</b-button><b-button v-if="credentialsError" size="sm" variant="outline-secondary" @click="loadCredentials">Retry loading credentials</b-button><span role="status">{{ notice }}</span></div><ScriptEditor v-model="code" language="python"/></div>
</section></template>
<script>
import {farmClientCommand} from '../farmClient.mjs';
import ScriptEditor from '../components/ScriptEditor.vue';
const statuses=[{key:'QUEUED',label:'Queued'},{key:'SUBMITTING',label:'Submitting'},{key:'ACCEPTED',label:'Accepted'},{key:'REJECTED',label:'Rejected'},{key:'SKIPPED',label:'Expired'}];
export default {components:{ScriptEditor},data:()=>({statuses,tabs:[{key:'flags',label:'Flags'},{key:'teams',label:'Teams'},{key:'client',label:'Exploit and client'}],tab:'flags',summary:{groups:[]},config:{targets:[]},flags:[],total:0,page:1,filters:{status:'',team:'',sploit:'',search:'',since:'',until:''},manual:false,text:'',notice:'',error:'',loading:false,sending:false,paused:false,timer:null,stopped:false,filename:'sploit.py',protocol:'HTTP',port:80,path:'/',code:'',credentials:null,credentialsError:''}),
 computed:{counts(){const v={};for(const g of this.summary.groups)v[g.status]=(v[g.status]||0)+g.count;return v},totalAll(){return Object.values(this.counts).reduce((a,b)=>a+b,0)},teamOptions(){return [{value:'',text:'All teams'},...[...new Set([...this.config.targets.map(t=>t.name),...this.summary.groups.map(g=>g.team)])].map(x=>({value:x,text:x}))]},sploitOptions(){return [{value:'',text:'All exploits'},...[...new Set(this.summary.groups.map(g=>g.sploit))].map(x=>({value:x,text:x}))]},command(){return this.credentials?farmClientCommand({server:location.origin,...this.credentials,filename:this.filename}):(this.credentialsError||'Loading command…')}},
 watch:{tab(value){if(value==='client'&&!this.credentials)this.loadCredentials()}},
 mounted(){this.generate();this.refresh();this.timer=setInterval(()=>{if(!this.paused&&!document.hidden)this.refresh()},3000)},beforeDestroy(){this.stopped=true;clearInterval(this.timer)},methods:{
 async loadCredentials(){this.credentialsError='';try{const {data}=await this.$http.post('/v2/farm/client-credentials');if(!this.stopped)this.credentials=data}catch{if(!this.stopped)this.credentialsError='Could not load client credentials'}},
 async refresh(){if(this.loading||this.stopped)return;this.loading=true;try{const params={...this.filters,page:this.page};for(const k of ['since','until'])if(params[k])params[k]=new Date(params[k]).toISOString();const [f,s,c]=await Promise.all([this.$http.get('/v2/farm/flags',{params}),this.$http.get('/v2/farm/summary'),this.$http.get('/v2/farm/config')]);if(this.stopped)return;this.flags=f.data.flags;this.total=f.data.total;this.summary=s.data;this.config=c.data;this.error=''}catch(e){if(!this.stopped)this.error=e.response?.data?.error||e.message}finally{this.loading=false}},
 apply(){this.page=1;this.refresh()},selectStatus(s){this.filters.status=s;this.apply()},reset(){this.filters={status:'',team:'',sploit:'',search:'',since:'',until:''};this.apply()},
 label(s){return statuses.find(x=>x.key===s)?.label||s},date(v){return new Date(v).toLocaleTimeString('en-US')+' · '+new Date(v).toLocaleDateString('en-US')},teamCount(team,status){return this.summary.groups.filter(g=>g.team===team&&g.status===status).reduce((n,g)=>n+g.count,0)},
 async submit(){this.sending=true;this.notice='';try{const {data}=await this.$http.post('/v2/farm/flags',{text:this.text});this.notice=`Added: ${data.inserted}; duplicates: ${data.duplicates}`;this.text='';this.page=1;await this.refresh()}catch(e){this.error=e.response?.data?.error||e.message}finally{this.sending=false}},
 async copy(v){try{await navigator.clipboard.writeText(v);this.notice='Copied'}catch{this.notice='Copy unavailable; download the file instead'}},
 download(v,name){const url=URL.createObjectURL(new Blob([v],{type:'text/x-python'}));const a=document.createElement('a');a.href=url;a.download=name.endsWith('.py')?name:name+'.py';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)},
 generate(){const port=Math.max(1,Math.min(65535,Number(this.port)||80));const common=`#!/usr/bin/env python3\nimport sys\n\nHOST = sys.argv[1]\nPORT = ${port}\n\n`;this.code=common+(this.protocol==='HTTP'?`import requests\n\n# Replace this request with your service-specific exploit.\nresponse = requests.get(f"http://{HOST}:{PORT}" + ${JSON.stringify(this.path)}, timeout=5)\ndata = response.text\n`:`import socket\n\n# Replace this exchange with your service-specific exploit.\nwith socket.create_connection((HOST, PORT), timeout=5) as connection:\n    connection.sendall(b"hello\\n")\n    data = connection.recv(1048576).decode(errors="replace")\n`)+`\nprint(data, flush=True)\n`},
 }};
</script>
<style scoped>
.farm-page{display:flex;flex-direction:column;gap:12px;max-width:1800px;margin:auto;padding:16px}.farm-header,.farm-actions,.farm-chips,.farm-tabs,.farm-pagination{display:flex;align-items:center;gap:8px;flex-wrap:wrap}.farm-header h1{font-size:21px;margin:0}.farm-actions{margin-left:auto}.farm-state{font-size:12px;color:var(--gm-muted)}.farm-state.running{color:var(--gm-success)}.farm-tabs{padding-bottom:10px;border-bottom:1px solid var(--gm-border)}.farm-chips .btn{border-radius:20px}.farm-manual{padding:12px;background:var(--gm-panel);border:1px solid var(--gm-border);border-radius:8px}.farm-filters{display:flex;align-items:end;gap:8px;flex-wrap:wrap}.farm-filters label{font-size:12px;margin:0;flex:1;min-width:135px}.farm-table{overflow:auto;border:1px solid var(--gm-border);border-radius:8px}.farm-table table{width:100%;font-size:13px}.farm-table th{color:var(--gm-muted);font-size:12px;background:var(--gm-panel);white-space:nowrap}.farm-table td,.farm-table th{padding:9px 12px;border-bottom:1px solid var(--gm-border)}.farm-table td small{display:block;color:var(--gm-muted)}.farm-copy{background:none;border:0;text-align:left;padding:0;max-width:400px;overflow-wrap:anywhere}.farm-response{max-width:380px;overflow-wrap:anywhere}.farm-badge{font-size:12px;white-space:nowrap;color:var(--gm-muted)}.accepted{color:var(--gm-success)}.rejected{color:var(--gm-danger)}.submitting{color:var(--gm-info)}.farm-empty{text-align:center;height:180px;color:var(--gm-muted)}.farm-pagination{justify-content:flex-end}.farm-pagination>span:first-child{margin-right:auto;font-size:12px}.farm-builder{display:grid;grid-template-columns:300px minmax(0,1fr);gap:16px;min-height:550px}.farm-builder-controls{display:flex;flex-direction:column;gap:10px}.farm-builder-controls h2{font-size:16px}.farm-builder-controls label{font-size:12px;margin:0}.farm-command{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}.farm-builder>.script-editor{min-height:550px;max-height:75vh}@media(max-width:800px){.farm-builder{grid-template-columns:1fr}.farm-page{padding:10px}.farm-header>.farm-actions{margin-left:0}.farm-copy{max-width:240px}}
</style>
